{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/0"],
      "relevance": "상담사가 '여기 앉아 있는 게 억울한 이유'를 짚어보자고 제안한 것과 직접 연결됨. 내담자는 이 자리가 자신에게 적용될 자리가 아니라고 느끼고 있으며, 이는 '특별한 사람이므로 보통 사람에게 적용되는 규칙이 자신에게 적용되어서는 안 된다'는 핵심 신념의 발현. /situations/0에서 인사팀장이 상담 이수를 통보했을 때 '3년 연속 1등 만들어 준 사람한테 지금 뭐 하자는 거야'라는 자동사고가 나타난 것과 동일한 패턴."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '말 안 하자니 시간이 안 줄고, 따지자니 맞다고만 하고'라며 좌절하는 것은, 보통 사람들과 같은 취급(정해진 시간, 정해진 절차)을 받는 것이 곧 '특별할 것 없는 그저 그런 사람으로 전락'하는 경험으로 느껴지기 때문. /situations/0에서 상담 프로그램 이수를 '나를 가르치려 드는' 모욕으로 반응한 것과 같은 구조."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '시켜서 온 거고요, 빨리 끝내죠', '있을 필요가 없는 자리에 앉아 있는 겁니다'라며 이 자리를 형식적으로만 임하고 깎아내리려는 태도는, 통제할 수 없는 자리(상담)를 '시간 낭비'로 규정하는 전략. 상담사의 제안에 대해 '하고 싶지 않으시면 그것도 괜찮습니다'라는 조건이 붙은 것도 이 전략을 우회하려는 시도와 관련."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 제안한 '억울한 이유를 짚어보는 것'은 내담자가 손상된 한계(자신은 규칙·한계에서 면제되어야 한다는 신념)를 가지고 있음을 전제함. /childhood_data에서 어머니가 문제를 무마해주고 교사들이 잘못을 문제 삼지 않았던 경험이 '나는 한계 바깥의 존재'라는 신념의 근원."
    }
  ]
}

